-- Solo lectura; comprobar tras aplicación y reejecución, sin asumir tablas vacías.
SELECT 'tabla_c10' control,1-COUNT(*) errores FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='cont_asientos_origen_revisiones' AND ENGINE='InnoDB';
SELECT 'columnas_c10' control,16-COUNT(*) errores FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='cont_asientos_origen_revisiones' AND COLUMN_NAME IN ('empresa_id','entidad_id','asiento_id','ejercicio_id','version','tipo','clase_anterior','clase','referencia','justificacion','huella_anterior','huella_asiento','clave_idempotencia','huella_solicitud','registrado_por','creado_en');
SELECT 'constraints_c10' control,4-COUNT(*) errores FROM information_schema.TABLE_CONSTRAINTS WHERE CONSTRAINT_SCHEMA=DATABASE() AND TABLE_NAME='cont_asientos_origen_revisiones' AND CONSTRAINT_NAME IN ('fk_c10_origen','fk_c10_ejercicio','fk_c10_usuario','ck_c10_revision');
SELECT 'indices_c10' control,2-COUNT(*) errores FROM (SELECT INDEX_NAME n,GROUP_CONCAT(COLUMN_NAME ORDER BY SEQ_IN_INDEX) cols FROM information_schema.STATISTICS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='cont_asientos_origen_revisiones' AND NON_UNIQUE=0 GROUP BY INDEX_NAME) i WHERE (n='PRIMARY' AND cols='empresa_id,entidad_id,asiento_id,version') OR (n='uq_c10_clave' AND cols='empresa_id,entidad_id,clave_idempotencia');
SELECT 'inmutabilidad_c10' control,2-COUNT(*) errores FROM information_schema.TRIGGERS WHERE TRIGGER_SCHEMA=DATABASE() AND EVENT_OBJECT_TABLE='cont_asientos_origen_revisiones' AND ACTION_TIMING='BEFORE' AND ((TRIGGER_NAME='c10_historial_no_update' AND EVENT_MANIPULATION='UPDATE') OR (TRIGGER_NAME='c10_historial_no_delete' AND EVENT_MANIPULATION='DELETE')) AND ACTION_STATEMENT LIKE '%SIGNAL SQLSTATE%45000%';
